    # Defensive defaults
    x = observation.get("player", {}).get("x", 0)
    y = observation.get("player", {}).get("y", 0)

    # Look for resources, threats, or territory control signals with safe fallbacks
    grid = observation.get("grid", [])
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0

    # Scan neighboring cells for positive signals
    best_dx, best_dy = 0, 0
    best_score = -float("inf")

