        for dx in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if nx < 0 or ny < 0 or ny >= height or nx >= width:
                continue
            cell = observation.get("grid", [])[ny][nx] if height > 0 and width > 0 else {}
            cell_type = cell.get("type") if isinstance(cell, dict) else None

            score = 0
            # Resource spots
            if cell_type == "resource":
                score += 2
            # Opponents nearby (pursuit_evasion)
            if cell_type == "enemy":
                score += 1
            # Territory control hints
            if cell_type == "control":
                score += 1
            # Empty or neutral
            if cell_type is None:
                score += 0.5

            if score > best_score:
                best_score = score
                best_dx, best_dy = dx, dy

    # If no movement found (edge cases), stay put
    if best_dx == 0 and best_dy == 0:
        return [0, 0]
    return [best_dx, best_dy]

